class EloPetApp extends StatelessWidget {
 const EloPetApp({super.key});
 @override Widget build(BuildContext context)=>MaterialApp(title:'EloPet',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF176B55)),useMaterial3:true,scaffoldBackgroundColor:const Color(0xFFFBFAF6)),home:const AuthGate());
