 Future<void> google()async{setState(()=>busy=true);try{final account=await GoogleSignIn.instance.authenticate();final credential=GoogleAuthProvider.credential(idToken:account.authentication.idToken);final result=await FirebaseAuth.instance.signInWithCredential(credential);final u=result.user!,profile=FirebaseFirestore.instance.collection('users').doc(result.user!.uid),existing=await profile.get();if(!existing.exists)await profile.set({'uid':u.uid,'email':u.email,'name':u.displayName,'photoUrl':u.photoURL,'role':'user','createdAt':FieldValue.serverTimestamp()});}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.pets,size:68,color:Color(0xFF176B55)),const Text('EloPet',textAlign:TextAlign.center,style:TextStyle(fontSize:36,fontWeight:FontWeight.bold)),const Text('Conectando pessoas e animais',textAlign:TextAlign.center),const SizedBox(height:24),if(creating)TextField(controller:name,decoration:const InputDecoration(labelText:'Nome completo')),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'E-mail')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Senha (mínimo 6 caracteres)')),if(error.isNotEmpty)Text(error,style:const TextStyle(color:Colors.red)),const SizedBox(height:12),FilledButton(onPressed:busy?null:()=>runAuth(create:creating),child:Text(creating?'Criar conta':'Entrar')),TextButton(onPressed:busy?null:()=>setState(()=>creating=!creating),child:Text(creating?'Já tenho conta':'Criar uma conta')),OutlinedButton.icon(onPressed:busy?null:google,icon:const Icon(Icons.login),label:const Text('Continuar com Google'))])))));
 }
}
class HomePage extends StatefulWidget {const HomePage({super.key});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{
 int tab=0;String role='user';final uid=FirebaseAuth.instance.currentUser!.uid;
 @override void initState(){super.initState();FirebaseFirestore.instance.collection('users').doc(uid).get().then((s){if(mounted)setState(()=>role=s.data()?['role']??'user');});}
 @override Widget build(BuildContext context){final pages=<Widget>[const AnimalPage(),const LostFoundPage(),const HelpPage(),const RequestsPage(),const ProfilePage(),if(role=='admin')const AdminPage()];final labels=<NavigationDestination>[const NavigationDestination(icon:Icon(Icons.pets),label:'Adoção'),const NavigationDestination(icon:Icon(Icons.search),label:'Perdidos'),const NavigationDestination(icon:Icon(Icons.volunteer_activism),label:'Ajude'),const NavigationDestination(icon:Icon(Icons.inbox),label:'Pedidos'),const NavigationDestination(icon:Icon(Icons.person),label:'Perfil'),if(role=='admin')const NavigationDestination(icon:Icon(Icons.admin_panel_settings),label:'Admin')];if(tab>=pages.length)tab=0;return Scaffold(appBar:AppBar(title:const Text('EloPet 🐾'),actions:[IconButton(tooltip:'Sair',onPressed:()=>FirebaseAuth.instance.signOut(),icon:const Icon(Icons.logout))]),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,destinations:labels,onDestinationSelected:(i)=>setState(()=>tab=i)));}
}
class AnimalPage extends StatelessWidget {const AnimalPage({super.key});@override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.all(16),child:Row(children:[const Expanded(child:Text('Encontre seu novo melhor amigo',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:()=>showRecordForm(context,'animals'),icon:const Icon(Icons.add),label:const Text('Anunciar'))])),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('animals').where('status',isEqualTo:'approved').snapshots(),builder:(context,s){if(s.hasError)return Center(child:Text('Erro: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Ainda não há animais aprovados.'));return ListView.builder(padding:const EdgeInsets.all(12),itemCount:s.data!.docs.length,itemBuilder:(context,i){final d=s.data!.docs[i],a=d.data();return Card(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[if((a['photoUrl']??'').toString().isNotEmpty)Image.network(a['photoUrl'],height:190,fit:BoxFit.cover),ListTile(leading:const Icon(Icons.pets),title:Text(a['name']??'Animal'),subtitle:Text('${a['species']??''} · ${a['city']??''}\n${a['description']??''}'),isThreeLine:true,trailing:IconButton(icon:const Icon(Icons.favorite_border),onPressed:()=>sendAdoption(context,d.id,a['ownerId']))),Padding(padding:const EdgeInsets.fromLTRB(16,0,16,14),child:FilledButton(onPressed:()=>sendAdoption(context,d.id,a['ownerId']),child:const Text('Tenho interesse')))]));});}))]);}
}
Future<void> sendAdoption(BuildContext context,String animalId,String ownerId)async{final uid=FirebaseAuth.instance.currentUser!.uid;if(uid==ownerId){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Este anúncio é seu.')));return;}try{await FirebaseFirestore.instance.collection('adoptionRequests').add({'animalId':animalId,'ownerId':ownerId,'requesterId':uid,'status':'pending','createdAt':FieldValue.serverTimestamp()});if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Solicitação enviada!')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
class LostFoundPage extends StatelessWidget {const LostFoundPage({super.key});@override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.all(16),child:Row(children:[const Expanded(child:Text('Ajude a reunir famílias',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold))),FilledButton(onPressed:()=>showRecordForm(context,'lostFound'),child:const Text('Publicar aviso'))])),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('lostFound').where('status',isEqualTo:'approved').snapshots(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(leading:const Icon(Icons.pets),title:Text('${x['kind']??''} · ${x['species']??''}'),subtitle:Text('${x['city']??''}\n${x['description']??''}'),isThreeLine:true);}).toList());}))]);}
class HelpPage extends StatelessWidget {const HelpPage({super.key});@override Widget build(BuildContext context){final options=[('Lar temporário','fosterApplications',Icons.home),('Oferecer doação','donations',Icons.volunteer_activism),('Ser voluntário','volunteers',Icons.people),('Fazer denúncia','reports',Icons.report),('Cadastrar clínica','clinics',Icons.local_hospital)];return ListView(padding:const EdgeInsets.all(16),children:[const Text('Sua ajuda transforma vidas',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),...options.map((o)=>Card(child:ListTile(leading:Icon(o.$3),title:Text(o.$1),trailing:const Icon(Icons.chevron_right),onTap:()=>showRecordForm(context,o.$2))))]);}}
class RequestsPage extends StatelessWidget {const RequestsPage({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser!.uid;return StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('adoptionRequests').where('requesterId',isEqualTo:uid).snapshots(),builder:(context,s){if(s.hasError)return Center(child:Text(s.error.toString()));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Você ainda não enviou pedidos.'));return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(title:Text('Pedido de adoção'),subtitle:Text('Status: ${x['status']}'),trailing:IconButton(icon:const Icon(Icons.chat),onPressed:()=>openChat(context,x['ownerId'],x['animalId'])));}).toList());});}}
class ProfilePage extends StatelessWidget {const ProfilePage({super.key});@override Widget build(BuildContext context){final u=FirebaseAuth.instance.currentUser!;return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(future:FirebaseFirestore.instance.collection('users').doc(u.uid).get(),builder:(context,s){final x=s.data?.data()??{};return ListView(padding:const EdgeInsets.all(20),children:[CircleAvatar(radius:36,child:Text((x['name']??u.email??'E').toString().substring(0,1).toUpperCase())),const SizedBox(height:12),Text(x['name']??u.displayName??'Usuário',textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text(u.email??'',textAlign:TextAlign.center),const SizedBox(height:20),ListTile(title:const Text('Cidade'),subtitle:Text(x['city']??'Não informada')),ListTile(title:const Text('Telefone'),subtitle:Text(x['phone']??'Não informado')),FilledButton(onPressed:()=>editProfile(context,x),child:const Text('Editar perfil'))]);});}}
Future<void> editProfile(BuildContext context,Map<String,dynamic> current)async{final name=TextEditingController(text:current['name']??''),city=TextEditingController(text:current['city']??''),phone=TextEditingController(text:current['phone']??'');await showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Editar perfil'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Nome')),TextField(controller:city,decoration:const InputDecoration(labelText:'Cidade')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Telefone'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()async{await FirebaseFirestore.instance.collection('users').doc(FirebaseAuth.instance.currentUser!.uid).update({'name':name.text.trim(),'city':city.text.trim(),'phone':phone.text.trim(),'updatedAt':FieldValue.serverTimestamp()});if(c.mounted)Navigator.pop(c);},child:const Text('Salvar'))]));}
class AdminPage extends StatelessWidget {const AdminPage({super.key});static const types=['animals','lostFound','fosterApplications','donations','volunteers','reports','clinics'];@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(12),children:[const Text('Central de aprovação',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),...types.map((type)=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection(type).where('status',isEqualTo:'pending').snapshots(),builder:(context,s){if(!s.hasData||s.data!.docs.isEmpty)return const SizedBox.shrink();return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(type,style:const TextStyle(fontWeight:FontWeight.bold)),...s.data!.docs.map((d)=>Card(child:ListTile(title:Text(d.data()['name']??d.data()['kind']??d.data()['city']??type),subtitle:Text(d.data()['description']??''),trailing:Wrap(children:[IconButton(icon:const Icon(Icons.check,color:Colors.green),onPressed:()=>review(context,type,d.id,'approved')),IconButton(icon:const Icon(Icons.close,color:Colors.red),onPressed:()=>review(context,type,d.id,'rejected'))]))))]);}))]);}
}
Future<void> review(BuildContext context,String collectionName,String id,String status)async{try{await FirebaseFirestore.instance.collection(collectionName).doc(id).update({'status':status,'reviewedBy':FirebaseAuth.instance.currentUser!.uid,'reviewedAt':FieldValue.serverTimestamp()});}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
Future<void> openChat(BuildContext context,String otherUid,String animalId)async{final uid=FirebaseAuth.instance.currentUser!.uid,ids=[uid,otherUid]..sort(),key='${ids.join('_')}_$animalId';final conv=FirebaseFirestore.instance.collection('conversations').doc(key);final snap=await conv.get();if(!snap.exists)await conv.set({'memberIds':ids,'animalId':animalId,'createdAt':FieldValue.serverTimestamp(),'lastMessage':''});if(!context.mounted)return;Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatPage(conversationId:key)));}
class ChatPage extends StatefulWidget{final String conversationId;const ChatPage({super.key,required this.conversationId});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final text=TextEditingController();Future<void> send()async{final v=text.text.trim();if(v.isEmpty)return;final uid=FirebaseAuth.instance.currentUser!.uid,ref=FirebaseFirestore.instance.collection('conversations').doc(widget.conversationId);await ref.collection('messages').add({'senderId':uid,'text':v,'createdAt':FieldValue.serverTimestamp()});await ref.update({'lastMessage':v,'lastMessageAt':FieldValue.serverTimestamp()});text.clear();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Conversa EloPet')),body:Column(children:[Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('conversations').doc(widget.conversationId).collection('messages').orderBy('createdAt').snapshots(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final m=d.data(),mine=m['senderId']==FirebaseAuth.instance.currentUser!.uid;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Card(color:mine?Theme.of(context).colorScheme.primaryContainer:null,child:Padding(padding:const EdgeInsets.all(12),child:Text(m['text']??''))));}).toList());})),SafeArea(child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:text,decoration:const InputDecoration(hintText:'Mensagem'))),IconButton(onPressed:send,icon:const Icon(Icons.send))])))]));}
}
Future<void> showRecordForm(BuildContext context,String type)async{final fields=<String,TextEditingController>{};final labels=<String,String>{'animals':'Nome,Espécie,Idade,Cidade,Descrição','lostFound':'Tipo (Perdido/Encontrado),Espécie,Cidade,Descrição','fosterApplications':'Cidade,Tipo de residência,Experiência e espaço','donations':'Tipo de doação,Cidade,Detalhes','volunteers':'Habilidades,Cidade,Disponibilidade','reports':'Local,Descrição,Contato','clinics':'Nome da clínica,Cidade,Telefone,Endereço,Serviços'}[type]!.split(',');for(var i=0;i<labels.length;i++)fields['f$i']=TextEditingController();XFile? image;bool busy=false;
 await showDialog(context:context,builder:(dialogContext)=>StatefulBuilder(builder:(context,setState)=>AlertDialog(title:Text('Novo registro'),content:SizedBox(width:420,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[...labels.asMap().entries.map((e)=>TextField(controller:fields['f${e.key}'],maxLines:e.value.contains('Descrição')||e.value.contains('Detalhes')||e.value.contains('Experiência')?3:1,decoration:InputDecoration(labelText:e.value))),if(type=='animals')TextButton.icon(onPressed:()async{final picked=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:80);if(picked!=null)setState(()=>image=picked);},icon:const Icon(Icons.photo),label:Text(image==null?'Adicionar foto':'Foto selecionada'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(dialogContext),child:const Text('Cancelar')),FilledButton(onPressed:busy?null:()async{setState(()=>busy=true);try{final uid=FirebaseAuth.instance.currentUser!.uid;final keys=<String,List<String>>{'animals':['name','species','age','city','description'],'lostFound':['kind','species','city','description'],'fosterApplications':['city','homeType','description'],'donations':['kind','city','description'],'volunteers':['skills','city','availability'],'reports':['city','description','contact'],'clinics':['name','city','phone','address','description']}[type]!;final data=<String,dynamic>{for(var i=0;i<keys.length;i++)keys[i]:fields['f$i']!.text.trim(),'status':'pending','createdAt':FieldValue.serverTimestamp()};data[type=='animals'?'ownerId':type=='lostFound'?'authorId':type=='reports'?'reporterId':'userId']=uid;if(type=='animals'&&image!=null){final file=File(image!.path),storageRef=FirebaseStorage.instance.ref('animals/$uid/${DateTime.now().millisecondsSinceEpoch}.jpg');await storageRef.putFile(file,SettableMetadata(contentType:'image/jpeg'));data['photoUrl']=await storageRef.getDownloadURL();}await FirebaseFirestore.instance.collection(type).add(data);if(dialogContext.mounted)Navigator.pop(dialogContext);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enviado para aprovação.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(context.mounted)setState(()=>busy=false);}},child:Text(busy?'Enviando...':'Enviar'))]})));
}
